        "type": "object",
        "additionalProperties": false,
        "properties": {
          "position_interpolation": {
            "enum": [
              "catmull-rom",
              "linear",
              "bezier"
            ],
            "description": "How positions between keyframes are drawn."
          },
          "rotation_interpolation": {
            "enum": [
              "slerp",
              "linear"
            ],
            "description": "How the view direction turns between keyframes."
          },
          "easing": {
            "enum": [
              "linear",
              "ease-in-out",
              "ease-in",
              "ease-out"
            ],
            "description": "How each transition speeds up and slows down."
          },
          "speed": {
            "type": "integer",
            "minimum": 1,
            "maximum": 100,
            "description": "Speed of automatic transitions, 1 (very slow) to 100 (very fast)."
          },
          "loop": {
            "type": "boolean",
            "description": "Play the path again from its start when it ends."
          },
          "autoplay": {
            "type": "boolean",
            "description": "Start playing as soon as the path has two keyframes."
          }
        }
